create table if not exists public.aktarim_michelin (
  i int primary key, ad text not null, url text not null, il text not null, yer text, etiket text not null,
  core text, k text, yesil boolean not null default false, mekan_id text, durum text not null default 'bekliyor', not_ text);
alter table public.aktarim_michelin enable row level security;
create table if not exists public.aktarim_michelin_aday (i int, mekan_id text, ad text, kategori text, ilce text, s real);
alter table public.aktarim_michelin_aday enable row level security;
on conflict (i) do nothing;